package com.familygrowth.android.remote

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import java.net.HttpURLConnection
import java.net.URL
import java.io.IOException
import java.time.Instant
import java.util.UUID
import java.time.LocalDate
import com.familygrowth.android.core.SchoolStage

interface FamilyApiTransport{
 suspend fun login(base:String,family:String,parent:String,pin:String):RemoteResult<String>
 suspend fun childSession(base:String,parentToken:String,child:String):RemoteResult<String>
 suspend fun snapshot(base:String,token:String,family:String,child:String):RemoteResult<RemoteSnapshot>
 suspend fun experience(base:String,token:String,family:String,child:String):RemoteResult<RemoteExperienceProfile>
 suspend fun updateExperience(base:String,token:String,family:String,child:String,birthDate:LocalDate,stageOverride:SchoolStage?,overrideReason:String,hapticsEnabled:Boolean,expectedVersion:Long):RemoteResult<RemoteExperienceProfile>
 suspend fun educationSources(base:String,token:String,family:String):RemoteResult<List<RemoteEducationSource>>
 suspend fun createEducationSource(base:String,token:String,family:String,title:String,sourceUrl:String,stages:List<SchoolStage>,usageNote:String,key:String):RemoteResult<RemoteEducationSource>
 suspend fun educationSourceAction(base:String,token:String,family:String,source:String,action:String,key:String):RemoteResult<RemoteEducationSource>
 suspend fun childEducationCatalog(base:String,token:String,family:String,child:String):RemoteResult<List<RemoteChildEducationSource>>
 suspend fun learningAssignments(base:String,token:String,family:String,child:String):RemoteResult<List<RemoteLearningAssignment>> = RemoteResult.Failure("课程同步暂不可用")
 suspend fun learningAttempt(base:String,token:String,family:String,child:String,assignment:String,activity:String,response:String,playedSeconds:Int?,durationSeconds:Int?,key:String):RemoteResult<RemoteLearningAssignment> = RemoteResult.Failure("活动提交暂不可用")
 suspend fun learningSubmit(base:String,token:String,family:String,child:String,assignment:String,expectedVersion:Long,key:String):RemoteResult<RemoteLearningAssignment> = RemoteResult.Failure("课节提交暂不可用")
 suspend fun learningReview(base:String,token:String,family:String,child:String,assignment:String,decision:String,note:String,expectedVersion:Long,key:String):RemoteResult<RemoteLearningAssignment> = RemoteResult.Failure("课程审核暂不可用")
 suspend fun teachingCourses(base:String,token:String,family:String):RemoteResult<List<RemoteCourseSummary>> = RemoteResult.Failure("课程工作台暂不可用")
 suspend fun teachingVersion(base:String,token:String,family:String,version:String):RemoteResult<RemoteTeachingVersion> = RemoteResult.Failure("课程版本暂不可用")
 suspend fun createTeachingCourse(base:String,token:String,family:String,stage:String,subject:String,courseTitle:String,lessonTitle:String,lessonSummary:String,activityType:String,activityTitle:String,instruction:String,contentRef:String?,key:String):RemoteResult<RemoteTeachingVersion> = RemoteResult.Failure("建课暂不可用")
 suspend fun publishTeachingVersion(base:String,token:String,family:String,version:String,key:String):RemoteResult<RemoteTeachingVersion> = RemoteResult.Failure("课程发布暂不可用")
 suspend fun assignTeachingLesson(base:String,token:String,family:String,child:String,version:String,lesson:String,key:String):RemoteResult<RemoteLearningAssignment> = RemoteResult.Failure("课程分配暂不可用")
 suspend fun submit(base:String,childToken:String,family:String,child:String,task:String,key:String):RemoteResult<Unit>
 suspend fun review(base:String,parentToken:String,family:String,completion:String,key:String):RemoteResult<Unit>
 suspend fun usage(base:String,childToken:String,family:String,child:String,key:String,occurredAt:Instant):RemoteResult<Unit>
}

class HttpFamilyApiTransport:FamilyApiTransport{
 override suspend fun login(base:String,family:String,parent:String,pin:String)=request(base,"/api/v1/auth/login","POST",null,JSONObject().put("familyId",family).put("parentId",parent).put("pin",pin)){it.getJSONObject("data").getString("token")}
 override suspend fun childSession(base:String,parentToken:String,child:String)=request(base,"/api/v1/auth/child-sessions","POST",parentToken,JSONObject().put("childId",child)){it.getJSONObject("data").getString("token")}
 override suspend fun snapshot(base:String,token:String,family:String,child:String)=request(base,"/api/v1/families/$family/children/$child/sync","GET",token,null){root->val d=root.getJSONObject("data");val w=d.getJSONObject("wallet");val a=d.getJSONArray("tasks");RemoteSnapshot(d.getString("familyId"),d.getString("childId"),d.getString("childName"),w.getString("moneyBalance").toBigDecimal(),w.getInt("coinBalance"),buildList{for(i in 0 until a.length()){val t=a.getJSONObject(i);add(RemoteTask(t.getString("id"),t.getString("title"),t.getInt("expectedMinutes"),t.getString("status"),if(t.isNull("latestCompletionId"))null else t.getString("latestCompletionId"))) }},d.getInt("pendingReviews"),d.getInt("approvedToday"))}
 override suspend fun experience(base:String,token:String,family:String,child:String)=request(base,"/api/v1/families/$family/children/$child/experience-profile","GET",token,null){decodeExperience(it.getJSONObject("data"))}
 override suspend fun updateExperience(base:String,token:String,family:String,child:String,birthDate:LocalDate,stageOverride:SchoolStage?,overrideReason:String,hapticsEnabled:Boolean,expectedVersion:Long)=request(base,"/api/v1/families/$family/children/$child/experience-profile","PUT",token,JSONObject().put("birthDate",birthDate.toString()).put("stageOverride",stageOverride?.name ?: JSONObject.NULL).put("overrideReason",overrideReason).put("hapticsEnabled",hapticsEnabled).put("expectedVersion",expectedVersion).put("auditReason","家长在 Android 端更新学习阶段")){decodeExperience(it.getJSONObject("data"))}
 override suspend fun educationSources(base:String,token:String,family:String)=request(base,"/api/v1/families/$family/education-resource-sources","GET",token,null){root->decodeEducationSources(root.getJSONArray("data"))}
 override suspend fun createEducationSource(base:String,token:String,family:String,title:String,sourceUrl:String,stages:List<SchoolStage>,usageNote:String,key:String)=request(base,"/api/v1/families/$family/education-resource-sources","POST",token,JSONObject().put("title",title).put("sourceUrl",sourceUrl).put("schoolStages",org.json.JSONArray(stages.map{it.name})).put("usageNote",usageNote),key){decodeEducationSource(it.getJSONObject("data"))}
 override suspend fun educationSourceAction(base:String,token:String,family:String,source:String,action:String,key:String)=request(base,"/api/v1/families/$family/education-resource-sources/$source/$action","POST",token,null,key){decodeEducationSource(it.getJSONObject("data"))}
 override suspend fun childEducationCatalog(base:String,token:String,family:String,child:String)=request(base,"/api/v1/families/$family/children/$child/education-resource-catalog","GET",token,null){root->val a=root.getJSONArray("data");buildList{for(i in 0 until a.length()){val d=a.getJSONObject(i);add(RemoteChildEducationSource(d.getString("id"),d.getString("title"),decodeCategories(d.getJSONArray("categories"),false),if(d.isNull("lastRefreshedAt"))null else d.getString("lastRefreshedAt"),d.getBoolean("parentActionRequired")))}}}
 override suspend fun learningAssignments(base:String,token:String,family:String,child:String)=request(base,"/api/v1/families/$family/children/$child/learning/assignments","GET",token,null){root->decodeLearningAssignments(root.getJSONArray("data"))}
 override suspend fun learningAttempt(base:String,token:String,family:String,child:String,assignment:String,activity:String,response:String,playedSeconds:Int?,durationSeconds:Int?,key:String)=request(base,"/api/v1/families/$family/children/$child/learning/assignments/$assignment/activities/$activity/attempts","POST",token,JSONObject().put("responseText",response).put("playedSeconds",playedSeconds?:JSONObject.NULL).put("durationSeconds",durationSeconds?:JSONObject.NULL),key){decodeLearningAssignment(it.getJSONObject("data"))}
 override suspend fun learningSubmit(base:String,token:String,family:String,child:String,assignment:String,expectedVersion:Long,key:String)=request(base,"/api/v1/families/$family/children/$child/learning/assignments/$assignment/submit","POST",token,JSONObject().put("expectedVersion",expectedVersion),key){decodeLearningAssignment(it.getJSONObject("data"))}
 override suspend fun learningReview(base:String,token:String,family:String,child:String,assignment:String,decision:String,note:String,expectedVersion:Long,key:String)=request(base,"/api/v1/families/$family/children/$child/learning/assignments/$assignment/review","POST",token,JSONObject().put("decision",decision).put("note",note).put("expectedVersion",expectedVersion),key){decodeLearningAssignment(it.getJSONObject("data"))}
 override suspend fun teachingCourses(base:String,token:String,family:String)=request(base,"/api/v1/families/$family/teaching/courses","GET",token,null){root->decodeCourseSummaries(root.getJSONArray("data"))}
 override suspend fun teachingVersion(base:String,token:String,family:String,version:String)=request(base,"/api/v1/families/$family/teaching/course-versions/$version","GET",token,null){decodeTeachingVersion(it.getJSONObject("data"))}
 override suspend fun createTeachingCourse(base:String,token:String,family:String,stage:String,subject:String,courseTitle:String,lessonTitle:String,lessonSummary:String,activityType:String,activityTitle:String,instruction:String,contentRef:String?,key:String):RemoteResult<RemoteTeachingVersion>{
  val activity=JSONObject().put("type",activityType).put("title",activityTitle).put("instruction",instruction).put("expectedMinutes",if(activityType=="SHORT_VIDEO")3 else 8)
  if(contentRef!=null)activity.put("contentRef",contentRef)
  val lesson=JSONObject().put("title",lessonTitle).put("summary",lessonSummary).put("activities",org.json.JSONArray().put(activity))
  val unit=JSONObject().put("title","家庭学习夹").put("lessons",org.json.JSONArray().put(lesson))
  val version=JSONObject().put("summary",lessonSummary).put("rightsBasis",if(activityType=="SHORT_VIDEO")"应用内原创审核视频" else "家庭原创学习活动").put("units",org.json.JSONArray().put(unit))
  val body=JSONObject().put("schoolStage",stage).put("subjectCode",subject).put("title",courseTitle).put("version",version)
  return request(base,"/api/v1/families/$family/teaching/courses","POST",token,body,key){decodeTeachingVersion(it.getJSONObject("data"))}
 }
 override suspend fun publishTeachingVersion(base:String,token:String,family:String,version:String,key:String)=request(base,"/api/v1/families/$family/teaching/course-versions/$version/publish","POST",token,null,key){decodeTeachingVersion(it.getJSONObject("data"))}
 override suspend fun assignTeachingLesson(base:String,token:String,family:String,child:String,version:String,lesson:String,key:String)=request(base,"/api/v1/families/$family/children/$child/learning/assignments","POST",token,JSONObject().put("courseVersionId",version).put("lessonId",lesson),key){decodeLearningAssignment(it.getJSONObject("data"))}
 override suspend fun submit(base:String,childToken:String,family:String,child:String,task:String,key:String)=request(base,"/api/v1/families/$family/children/$child/tasks/$task/completions","POST",childToken,JSONObject().put("evidenceNote","在孩子端确认完成"),key){Unit}
 override suspend fun review(base:String,parentToken:String,family:String,completion:String,key:String)=request(base,"/api/v1/families/$family/completions/$completion/review","POST",parentToken,JSONObject().put("approved",true).put("xpReward",10).put("coinReward",10).put("moneyReward",0).put("reviewNote","家长端确认"),key){Unit}
 override suspend fun usage(base:String,childToken:String,family:String,child:String,key:String,occurredAt:Instant)=request(base,"/api/v1/families/$family/children/$child/usage-events","POST",childToken,JSONObject().put("type","APP_ACTIVE").put("minutes",1).put("occurredAt",occurredAt.toString()),key){Unit}
 private suspend fun <T> request(base:String,path:String,method:String,token:String?,body:JSONObject?,key:String?=null,decode:(JSONObject)->T):RemoteResult<T> = withContext(Dispatchers.IO){
  try{val connection=(URL(base+path).openConnection() as HttpURLConnection).apply{requestMethod=method;connectTimeout=8_000;readTimeout=10_000;setRequestProperty("Accept","application/json");if(token!=null)setRequestProperty("Authorization","Bearer $token");if(key!=null)setRequestProperty("Idempotency-Key",key);if(body!=null){doOutput=true;setRequestProperty("Content-Type","application/json");outputStream.use{it.write(body.toString().toByteArray(Charsets.UTF_8))}}};val code=connection.responseCode;if(code==401){connection.disconnect();return@withContext RemoteResult.Unauthorized};val stream=if(code in 200..299)connection.inputStream else connection.errorStream;val text=stream?.bufferedReader()?.use{it.readText()}.orEmpty();connection.disconnect();if(code !in 200..299)return@withContext remoteFailureForStatus(code);RemoteResult.Ok(decode(JSONObject(text)))}catch(_:IOException){RemoteResult.Failure("无法连接家庭服务，记录已安全保留",RemoteFailureKind.RETRYABLE)}catch(_:Exception){RemoteResult.Failure("家庭服务返回了无法识别的数据")}
 }
 private fun decodeExperience(d:JSONObject)=RemoteExperienceProfile(d.getString("birthDate"),d.getString("recommendedStage"),if(d.isNull("stageOverride"))null else d.getString("stageOverride"),d.getString("effectiveStage"),d.optString("overrideReason"),d.getBoolean("hapticsEnabled"),d.getLong("version"))
 private fun decodeEducationSources(a:org.json.JSONArray)=buildList{for(i in 0 until a.length())add(decodeEducationSource(a.getJSONObject(i)))}
 private fun decodeEducationSource(d:JSONObject):RemoteEducationSource{val stages=d.getJSONArray("schoolStages");return RemoteEducationSource(d.getString("id"),d.getString("title"),d.getString("sourceUrl"),buildList{for(i in 0 until stages.length())add(stages.getString(i))},d.getString("usageNote"),d.getString("status"),d.getString("refreshStatus"),d.optString("refreshError"),if(d.isNull("lastRefreshedAt"))null else d.getString("lastRefreshedAt"),decodeCategories(d.getJSONArray("categories"),true))}
 private fun decodeCategories(a:org.json.JSONArray,parent:Boolean)=buildList{for(i in 0 until a.length()){val d=a.getJSONObject(i);add(RemoteResourceCategory(d.getString("id"),d.getString("title"),d.getInt("displayOrder"),if(parent&&!d.isNull("categoryUrl"))d.getString("categoryUrl") else null))}}
 private fun decodeLearningAssignments(a:org.json.JSONArray)=buildList{for(i in 0 until a.length())add(decodeLearningAssignment(a.getJSONObject(i)))}
 private fun decodeLearningAssignment(d:JSONObject):RemoteLearningAssignment{val activities=d.getJSONArray("activities");return RemoteLearningAssignment(d.getString("id"),d.getString("courseTitle"),d.getString("unitTitle"),d.getString("lessonTitle"),d.getString("lessonSummary"),d.getString("schoolStage"),d.getString("subjectCode"),d.getString("status"),d.getLong("version"),buildList{for(i in 0 until activities.length()){val a=activities.getJSONObject(i);val options=a.getJSONArray("options");val evidence=a.getJSONArray("evidence");add(RemoteLearningActivity(a.getString("id"),a.getString("type"),a.getString("title"),a.getString("instruction"),a.optString("contentRef"),a.getInt("expectedMinutes"),a.optString("prompt"),a.optString("hint"),buildList{for(j in 0 until options.length()){val o=options.getJSONObject(j);add(RemoteQuestionOption(o.getString("value"),o.getString("label")))}},a.getString("requiredEvidence"),buildSet{for(j in 0 until evidence.length())add(evidence.getString(j))},if(a.isNull("checkedCorrect"))null else a.getBoolean("checkedCorrect"))) }},d.optString("reviewNote"))}
 private fun decodeCourseSummaries(a:org.json.JSONArray)=buildList{for(i in 0 until a.length()){val d=a.getJSONObject(i);add(RemoteCourseSummary(d.getString("courseId"),d.getString("title"),d.getString("schoolStage"),d.getString("subjectCode"),d.getString("versionId"),d.getInt("versionNumber"),d.getString("status"),d.getInt("lessonCount")))}}
 private fun decodeTeachingVersion(d:JSONObject):RemoteTeachingVersion{val lessons=buildList{val units=d.getJSONArray("units");for(i in 0 until units.length()){val ls=units.getJSONObject(i).getJSONArray("lessons");for(j in 0 until ls.length())add(ls.getJSONObject(j).getString("id"))}};return RemoteTeachingVersion(d.getString("courseId"),d.getString("versionId"),d.getString("title"),d.getString("schoolStage"),d.getString("subjectCode"),d.getInt("versionNumber"),d.getString("status"),lessons)}
}

internal fun remoteFailureForStatus(code:Int):RemoteResult.Failure = when(code){
 409->RemoteResult.Failure("数据已变化，请刷新后重试",RemoteFailureKind.CONFLICT)
  408,425,429->RemoteResult.Failure("家庭服务暂时忙碌（$code）",RemoteFailureKind.RETRYABLE)
 in 500..599->RemoteResult.Failure("家庭服务暂时不可用（$code）",RemoteFailureKind.RETRYABLE)
 403->RemoteResult.Failure("当前角色无权执行")
 else->RemoteResult.Failure("服务请求失败（$code）")
}

class RemoteFamilyRepository(private val transport:FamilyApiTransport,private val sessions:MemorySessionStore,private val allowPrivateHttp:Boolean){
 suspend fun connect(rawBase:String,family:String,parent:String,child:String,pin:String):RemoteResult<RemoteSnapshot>{val base=ServiceUrlPolicy.normalize(rawBase,allowPrivateHttp).getOrElse{return RemoteResult.Failure(it.message?:"服务地址无效")};runCatching{validateConnectionIds(family,parent,child)}.getOrElse{return RemoteResult.Failure("家庭、家长或孩子 ID 格式无效")};val parentToken=when(val r=transport.login(base,family,parent,pin)){is RemoteResult.Ok->r.value;RemoteResult.Unauthorized->return RemoteResult.Unauthorized;is RemoteResult.Failure->return r};val childToken=when(val r=transport.childSession(base,parentToken,child)){is RemoteResult.Ok->r.value;RemoteResult.Unauthorized->return expired();is RemoteResult.Failure->return r};val session=RemoteSession(base,family,parent,child,parentToken,childToken);sessions.set(session);return refresh()}
 suspend fun refresh():RemoteResult<RemoteSnapshot>{val s=sessions.get()?:return RemoteResult.Failure("尚未连接家庭服务");val snapshot=when(val r=transport.snapshot(s.baseUrl,s.parentToken,s.familyId,s.childId)){is RemoteResult.Ok->r.value;RemoteResult.Unauthorized->return expired();is RemoteResult.Failure->return r};return when(val p=transport.experience(s.baseUrl,s.parentToken,s.familyId,s.childId)){is RemoteResult.Ok->RemoteResult.Ok(snapshot.copy(experience=p.value));RemoteResult.Unauthorized->expired();is RemoteResult.Failure->p}}
 suspend fun updateExperience(birthDate:LocalDate,stageOverride:SchoolStage?,overrideReason:String,hapticsEnabled:Boolean,expectedVersion:Long):RemoteResult<RemoteSnapshot>{val s=sessions.get()?:return RemoteResult.Failure("尚未连接家庭服务");return when(val r=transport.updateExperience(s.baseUrl,s.parentToken,s.familyId,s.childId,birthDate,stageOverride,overrideReason,hapticsEnabled,expectedVersion)){is RemoteResult.Ok->refresh();RemoteResult.Unauthorized->expired();is RemoteResult.Failure->r}}
 suspend fun educationSources():RemoteResult<List<RemoteEducationSource>>{val s=sessions.get()?:return RemoteResult.Failure("尚未连接家庭服务");return when(val r=transport.educationSources(s.baseUrl,s.parentToken,s.familyId)){RemoteResult.Unauthorized->expired();else->r}}
 suspend fun childEducationCatalog():RemoteResult<List<RemoteChildEducationSource>>{val s=sessions.get()?:return RemoteResult.Failure("尚未连接家庭服务");return when(val r=transport.childEducationCatalog(s.baseUrl,s.childToken,s.familyId,s.childId)){RemoteResult.Unauthorized->expired();else->r}}
 suspend fun learningAssignments():RemoteResult<List<RemoteLearningAssignment>>{val s=sessions.get()?:return RemoteResult.Failure("尚未连接家庭服务");return when(val r=transport.learningAssignments(s.baseUrl,s.childToken,s.familyId,s.childId)){RemoteResult.Unauthorized->expired();else->r}}
 suspend fun executeLearning(action:PendingLearningAction):RemoteResult<RemoteLearningAssignment>{val s=sessions.get()?:return RemoteResult.Failure("请家长重新连接后同步",RemoteFailureKind.RETRYABLE);if(s.familyId!=action.familyId||s.childId!=action.childId)return RemoteResult.Failure("待同步记录属于另一个家庭或孩子");val result=when(action.type){LearningActionType.ATTEMPT->transport.learningAttempt(s.baseUrl,s.childToken,s.familyId,s.childId,action.assignmentId,action.activityId,action.responseText,action.playedSeconds,action.durationSeconds,action.idempotencyKey);LearningActionType.SUBMIT->transport.learningSubmit(s.baseUrl,s.childToken,s.familyId,s.childId,action.assignmentId,action.expectedVersion?:return RemoteResult.Failure("待提交版本缺失"),action.idempotencyKey);LearningActionType.REVIEW->transport.learningReview(s.baseUrl,s.parentToken,s.familyId,s.childId,action.assignmentId,action.decision,action.note,action.expectedVersion?:return RemoteResult.Failure("待审核版本缺失"),action.idempotencyKey)};return when(result){RemoteResult.Unauthorized->expired();else->result}}
 suspend fun teachingCourses():RemoteResult<List<RemoteCourseSummary>>{val s=sessions.get()?:return RemoteResult.Failure("请先连接家庭服务");return when(val r=transport.teachingCourses(s.baseUrl,s.parentToken,s.familyId)){RemoteResult.Unauthorized->expired();else->r}}
 suspend fun createTeachingCourse(stage:String,subject:String,courseTitle:String,lessonTitle:String,lessonSummary:String,activityType:String,activityTitle:String,instruction:String,contentRef:String?):RemoteResult<RemoteTeachingVersion>{val s=sessions.get()?:return RemoteResult.Failure("请先连接家庭服务");return when(val r=transport.createTeachingCourse(s.baseUrl,s.parentToken,s.familyId,stage,subject,courseTitle,lessonTitle,lessonSummary,activityType,activityTitle,instruction,contentRef,UUID.randomUUID().toString())){RemoteResult.Unauthorized->expired();else->r}}
 suspend fun publishTeachingVersion(version:String):RemoteResult<RemoteTeachingVersion>{val s=sessions.get()?:return RemoteResult.Failure("请先连接家庭服务");return when(val r=transport.publishTeachingVersion(s.baseUrl,s.parentToken,s.familyId,version,UUID.randomUUID().toString())){RemoteResult.Unauthorized->expired();else->r}}
 suspend fun assignTeachingVersion(version:String):RemoteResult<RemoteLearningAssignment>{val s=sessions.get()?:return RemoteResult.Failure("请先连接家庭服务");val detail=when(val r=transport.teachingVersion(s.baseUrl,s.parentToken,s.familyId,version)){is RemoteResult.Ok->r.value;RemoteResult.Unauthorized->return expired();is RemoteResult.Failure->return r};val lesson=detail.lessonIds.firstOrNull()?:return RemoteResult.Failure("课程版本没有可分配课节");return when(val r=transport.assignTeachingLesson(s.baseUrl,s.parentToken,s.familyId,s.childId,version,lesson,UUID.randomUUID().toString())){RemoteResult.Unauthorized->expired();else->r}}
 suspend fun createEducationSource(title:String,url:String,stages:List<SchoolStage>,note:String):RemoteResult<List<RemoteEducationSource>>{val s=sessions.get()?:return RemoteResult.Failure("请先连接家庭服务");return when(val r=transport.createEducationSource(s.baseUrl,s.parentToken,s.familyId,title,url,stages,note,UUID.randomUUID().toString())){is RemoteResult.Ok->educationSources();RemoteResult.Unauthorized->expired();is RemoteResult.Failure->r}}
 suspend fun educationSourceAction(source:String,action:String):RemoteResult<List<RemoteEducationSource>>{val s=sessions.get()?:return RemoteResult.Failure("请先连接家庭服务");return when(val r=transport.educationSourceAction(s.baseUrl,s.parentToken,s.familyId,source,action,UUID.randomUUID().toString())){is RemoteResult.Ok->educationSources();RemoteResult.Unauthorized->expired();is RemoteResult.Failure->r}}
 suspend fun submitTask(taskId:String):RemoteResult<RemoteSnapshot>{val s=sessions.get()?:return RemoteResult.Failure("尚未连接家庭服务");return when(val r=transport.submit(s.baseUrl,s.childToken,s.familyId,s.childId,taskId,UUID.randomUUID().toString())){is RemoteResult.Ok->refresh();RemoteResult.Unauthorized->expired();is RemoteResult.Failure->r}}
 suspend fun approveTask(completionId:String):RemoteResult<RemoteSnapshot>{val s=sessions.get()?:return RemoteResult.Failure("尚未连接家庭服务");return when(val r=transport.review(s.baseUrl,s.parentToken,s.familyId,completionId,UUID.randomUUID().toString())){is RemoteResult.Ok->refresh();RemoteResult.Unauthorized->expired();is RemoteResult.Failure->r}}
 suspend fun recordUsage(key:String,occurredAt:Instant):RemoteResult<Unit>{val s=sessions.get()?:return RemoteResult.Failure("尚未连接家庭服务");return when(val r=transport.usage(s.baseUrl,s.childToken,s.familyId,s.childId,key,occurredAt)){RemoteResult.Unauthorized->expired();else->r}}
 fun learningScope():Pair<String,String>?=sessions.get()?.let{it.familyId to it.childId}
 fun disconnect(){sessions.clear()} fun hasSession()=sessions.get()!=null
 private fun <T> expired():RemoteResult<T>{sessions.clear();return RemoteResult.Unauthorized}
}
